--     match = { namespace = "^my-overlay$" },
--     no_anim = true,
-- })
-- overlayLayerRule:set_enabled(false)

-- Hyprland-run windowrule
hl.window_rule({
    name  = "move-hyprland-run",
    match = { class = "hyprland-run" },

    move  = "20 monitor_h-120",
    float = true,
})

-- Project Arch Phase 1 session services
hl.on("hyprland.start", function ()
    hl.exec_cmd("dbus-update-activation-environment --systemd WAYLAND_DISPLAY DISPLAY XDG_SESSION_TYPE XDG_CURRENT_DESKTOP HYPRLAND_INSTANCE_SIGNATURE && systemctl --user start plasma-polkit-agent.service")
    hl.exec_cmd(os.getenv("HOME") .. "/.local/bin/workstation-session")
end)

-- Iris workstation integration: native dispatchers, upstream shell shortcuts.
hl.env("PATH", os.getenv("HOME") .. "/.local/bin:" .. os.getenv("PATH"))
hl.env("XDG_DATA_DIRS", (os.getenv("XDG_DATA_DIRS") or "/usr/local/share:/usr/share") .. ":/var/lib/flatpak/exports/share:" .. os.getenv("HOME") .. "/.local/share/flatpak/exports/share")
hl.config({
    general = { gaps_in = 6, gaps_out = 12, resize_on_border = true },
    decoration = { blur = { size = 5, passes = 2, vibrancy = 0.0 } },
    master = { mfact = 0.55, new_status = "slave", orientation = "left" },
    input = { follow_mouse = 0 }, -- keyboard focus stays put until a click
})
hl.animation({ leaf = "windows", enabled = true, speed = 3, bezier = "easeOutQuint" })
hl.animation({ leaf = "windowsIn", enabled = true, speed = 3, bezier = "easeOutQuint", style = "popin 98%" })
hl.animation({ leaf = "windowsOut", enabled = true, speed = 3, bezier = "easeOutQuint", style = "popin 98%" })
hl.bind("SUPER + space", hl.dsp.exec_cmd(menu))
hl.bind("SUPER + Return", hl.dsp.exec_cmd(terminal))
hl.bind("SUPER + W", hl.dsp.exec_cmd(os.getenv("HOME") .. "/.local/bin/workstation-zen"))
hl.bind("SUPER + D", hl.dsp.exec_cmd(os.getenv("HOME") .. "/.local/bin/workstation-editor"))
hl.bind("SUPER + F", hl.dsp.window.fullscreen({ mode = "fullscreen" }))
hl.bind("SUPER + A", hl.dsp.global("caelestia:sidebar"))
hl.bind("SUPER + CTRL + V", hl.dsp.exec_cmd("caelestia clipboard"))
hl.bind("Print", hl.dsp.exec_cmd(os.getenv("HOME") .. "/.local/bin/workstation-screenshot region"))
hl.bind("SHIFT + Print", hl.dsp.exec_cmd(os.getenv("HOME") .. "/.local/bin/workstation-screenshot annotate"))
hl.bind("CTRL + Print", hl.dsp.exec_cmd(os.getenv("HOME") .. "/.local/bin/workstation-screenshot full"))
hl.bind("SUPER + F1", hl.dsp.exec_cmd("kitty less " .. os.getenv("HOME") .. "/arch-setup-report.md"))
-- Editor left; browser and terminal stacked right. Open in that order.
hl.bind("SUPER + CTRL + M", function() hl.config({ general = { layout = "master" } }) end)
hl.bind("SUPER + CTRL + D", function() hl.config({ general = { layout = "dwindle" } }) end)
for _, direction in ipairs({ "left", "right", "up", "down" }) do
    hl.bind("SUPER + SHIFT + " .. direction, hl.dsp.window.move({ direction = direction }))
end
for direction, delta in pairs({left={-40,0}, right={40,0}, up={0,-40}, down={0,40}}) do
    hl.bind("SUPER + CTRL + " .. direction,
        hl.dsp.window.resize({ x = delta[1], y = delta[2], relative = true }), { repeating = true })
end

-- Reference desktop: app-native glass, native shell blur, opt-in composition.
-- No compositor opacity multiplication: Kitty text stays fully opaque.
hl.window_rule({
    name = "kitty-native-glass",
    match = { class = "^(kitty|workstation-presentation)$" },
    opacity = "1.0 override 1.0 override",
    opaque = false,
    force_rgbx = false,
    no_blur = false,
})
hl.layer_rule({
    name = "caelestia-frosted-drawers",
    match = { namespace = "^caelestia-drawers$" },
    blur = true,
    ignore_alpha = 0.05,
})
hl.window_rule({
    name = "presentation-terminal-only",
    match = { class = "^workstation-presentation$" },
    float = true,
    size = "monitor_w*0.65 monitor_h*0.65",
    center = true,
})
-- Existing Super+V remains the plain float toggle.
hl.bind("SUPER + SHIFT + V", hl.dsp.exec_cmd(os.getenv("HOME") .. "/.local/bin/workstation-presentation"))
hl.bind("SUPER + SHIFT + Return", hl.dsp.exec_cmd("kitty --class workstation-presentation"))
hl.bind("SUPER + CTRL + F9", hl.dsp.exec_cmd(os.getenv("HOME") .. "/.local/bin/workstation-wallpaper A"))
hl.bind("SUPER + CTRL + F10", hl.dsp.exec_cmd(os.getenv("HOME") .. "/.local/bin/workstation-wallpaper B"))

-- Small launcher-only dock; Caelestia retains tray, status and notifications.

-- Rice refinement: stable compositor glass for unmodified Electron apps.
-- Whole-surface opacity also affects text; kept at 0.94 for readability.
hl.window_rule({
    name = "iris-code-glass",
    match = { class = "^(code-oss|Code)$" },
    opacity = "0.94 override 0.94 override",
    no_blur = false,
})

-- Compact controls use the same frosted layer blur as the dock.
hl.layer_rule({ name = "workstation-controls-glass", match = { namespace = "^workstation-controls$" }, blur = true, ignore_alpha = 0.02 })

-- Prevent blurry XWayland apps at fractional scaling
hl.config({
    xwayland = {
        force_zero_scaling = true,
    },
})

-- Modular workstation navigation; see arch-setup/completion/README.md.
dofile(os.getenv("HOME") .. "/.config/hypr/workflow.lua")

-- Scoped browser/application glass; no wallpaper or global opacity changes.
dofile(os.getenv("HOME") .. "/.config/hypr/glass.lua")

-- Project IRIS targeted additions.
dofile(os.getenv("HOME") .. "/.config/hypr/iris.lua")
